import time
import socket
import logging
from typing import List

from .tcp import TcpPdu
from .base import PduIdentificationType

from taf.hw.pdu.device_status import DeviceStatus

from ..exceptions import BadResponse, PduConnectionError


class DeltaElektronika(TcpPdu):
    def __init__(self, host: str, port: int = 8462, timeout: float = 10, retry_timeout: float = 2) -> None:
        super().__init__(host, port, timeout, retry_timeout)
        device_data = self.get_idn()
        logging.info(
            f"IDN information: brand({device_data[0]}), model({device_data[1]}), "
            f"serial number({device_data[2]}), version({device_data[3]})"
        )

    @property
    def _port_setting(self):
        """Dictionary of settings used to get PDU status/value"""
        return {
            DeviceStatus.OFF: "OFF",
            DeviceStatus.ON: "ON",
        }

    def _build_command(self, port, status):
        pass

    def _parse_response(self, response):
        pass

    def _check_error(self) -> None:
        error_response = self._execute_cmd("SYSTem:ERRor?\n")
        if "0,None" not in error_response:
            raise Exception(f"DTS SM3300 power supply error: {error_response}\n")

    def power_on(self, port=None) -> None:
        self._execute_cmd("SYSTem:FROntpanel ON\n")
        self._execute_cmd("OUTPut ON\n")
        time.sleep(1)
        self._execute_cmd("SYSTem:FROntpanel OFF\n")
        self._check_error()

    def power_off(self, port=None) -> None:
        self._execute_cmd("SYSTem:FROntpanel ON\n")
        self._execute_cmd("OUTPut OFF\n")
        time.sleep(1)
        self._execute_cmd("SYSTem:FROntpanel OFF\n")
        self._check_error()

    def get_current(self, port=None) -> float:
        response = self._get_measurement("current", "MEASure:CURRent?\n")
        return response

    def get_voltage(self, port=None) -> float:
        voltage = self._get_measurement("voltage", "MEASure:VOLTage?\n")
        return voltage

    def set_voltage(self, voltage, port=None) -> None:  # type: ignore[override]
        curr_voltage = self.get_voltage()
        if abs(curr_voltage - voltage) > 0.1:
            self._execute_cmd("SYSTem:FROntpanel ON\n")
            self._execute_cmd(f"SOURce:VOLTage {voltage}\n")
            time.sleep(1)
            self._execute_cmd("SYSTem:FROntpanel OFF\n")
            self._check_error()

    def get_idn(self) -> List[str]:
        info = self.get_pdu_info()
        if info.identification_type != PduIdentificationType.SCPI_IDN:
            raise PduConnectionError("Failed to fetch identification via SCPI")
        return [x.strip() for x in info.identifier.split(",")]

    def _get_measurement(self, name: str, command: str) -> float:
        logging.info(f"Fetching {name} value")
        try:
            response = self._execute_cmd_with_retry_on_timeout(command)
            value = float(response)
        except socket.error as e:
            logging.error(str(e))
            raise PduConnectionError(f"Error while fetching {name} value")
        except ValueError as e:
            raise BadResponse(str(e))
        return value
